const {chromium}=require('playwright');const {expect}=require('playwright/test');const assert=require('node:assert/strict');const fs=require('node:fs');
const output=process.env.DEEP_FOCUS_OUTPUT||'.superpowers/deep-audit/sticky-focus';
const sizes=[[320,700],[360,800],[390,844],[430,932],[768,1024],[1024,768],[1280,800],[1440,900]];
const cases=process.env.DEEP_FOCUS_SMOKE?[{width:390,height:844,language:'English + Bangla'}]:[...sizes.map(([width,height])=>({width,height,language:'English + Bangla'})),...['English','Bangla'].flatMap(language=>[sizes[2],sizes[7]].map(([width,height])=>({width,height,language})))];
const roles=['All','Customer','Supplier','Vendor','Lender','Borrower','Payee','Owner','Ledger'];const bnRoles=['সব','ক্রেতা','সরবরাহকারী','ভেন্ডর','ঋণদাতা','ঋণগ্রহীতা','খরচের প্রাপক','মালিক','খাতা'];
async function main(){const {createServer}=await import('vite');const server=await createServer({cacheDir:'.superpowers/sticky-focus-cache',server:{host:'127.0.0.1',port:4459,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});fs.mkdirSync(output,{recursive:true});const results=[];const axe=fs.readFileSync(require.resolve('axe-core/axe.min.js'),'utf8');
try{for(const {width,height,language} of cases)for(const theme of ['light','dark']){
 const bn=language==='Bangla',id=[language.replace(/\W/g,'-'),width,theme].join('-');const context=await browser.newContext({viewport:{width,height},hasTouch:width<=1024,colorScheme:theme,reducedMotion:'reduce'});await context.route('https://fonts.googleapis.com/**',r=>r.abort());await context.addInitScript(({language,theme})=>{if(location.protocol!=='http:')return;localStorage.setItem('hisabiq-theme',theme);localStorage.setItem('hisabiq-erp-personal-v1',JSON.stringify({language,mode:'Simple',density:'Compact',terminology:'simple',dateView:'transaction'}));},{language,theme});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{await page.goto('http://127.0.0.1:4459/#/saas/overview',{waitUntil:'domcontentloaded'});await page.locator('main').waitFor();await page.evaluate(()=>{document.documentElement.style.scrollPaddingTop='5px';location.hash='#/app/parties?id=c1&role=Customer';});const edit=page.getByRole('button',{name:bn?'তথ্য বদলান':'Edit party',exact:true});await edit.waitFor();for(const name of bn?bnRoles:roles){const tab=page.getByRole('tab',{name,exact:true});if(width<=1024)await tab.tap();else await tab.click();}
 await edit.focus();const geometry=await edit.evaluate(e=>{const r=e.getBoundingClientRect(),header=document.querySelector('header').getBoundingClientRect();return{top:r.top,headerBottom:header.bottom,centerHit:e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2))};});assert.ok(geometry.centerHit&&geometry.top>=geometry.headerBottom-1,'Focused Edit party stays clear of sticky search: '+JSON.stringify(geometry));
 await page.addScriptTag({content:axe});const violations=await page.evaluate(async()=>{const r=await axe.run(document,{runOnly:['target-size']});return r.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}));});assert.deepEqual(violations,[]);
 await edit.press('Enter');const dialog=page.getByRole('dialog',{name:bn?'পার্টির তথ্য বদলান':'Edit party',exact:true});await expect(dialog).toBeVisible();await dialog.getByRole('button',{name:bn?'বাতিল':'Cancel',exact:true}).click();await expect(dialog).toHaveCount(0);await expect(edit).toBeFocused();
 await page.setViewportSize({width:width<640?768:390,height:width<640?1024:844});await expect.poll(()=>page.evaluate(()=>parseFloat(document.documentElement.style.scrollPaddingTop)>=document.querySelector('header').getBoundingClientRect().height+7)).toBe(true);
 await page.evaluate(()=>location.hash='#/saas/overview');await expect.poll(()=>page.evaluate(()=>document.documentElement.style.scrollPaddingTop)).toBe('5px');assert.deepEqual(errors,[]);results.push({language,width,height,theme,status:'passed',geometry,violations});
 }catch(e){console.error(id,e.message);results.push({language,width,height,theme,status:'failed',error:e.message});await page.screenshot({path:output+'/'+id+'.png',fullPage:true});}
 const failed=results.at(-1).status==='failed';await context.tracing.stop(failed?{path:output+'/'+id+'-trace.zip'}:{});await context.close();console.log(id,failed?'failed':'passed');
}}finally{fs.writeFileSync(output+'/results.json',JSON.stringify(results,null,2));await browser.close();await server.close();}assert.equal(results.filter(r=>r.status==='failed').length,0);}
main().catch(e=>{console.error(e);process.exitCode=1;});
